#!/bin/bash
set -e

echo "=========================================================="
echo "  MAESTRO STUDIO: SYNC VPS + PUSH TO GITHUB (APK BUILD)   "
echo "=========================================================="

if [ -d "/var/www/maestro-studio" ]; then
    APP_DIR="/var/www/maestro-studio"
elif [ -d "/root/maestro-studio" ]; then
    APP_DIR="/root/maestro-studio"
elif [ -d "/home/maestro-studio" ]; then
    APP_DIR="/home/maestro-studio"
else
    APP_DIR="/var/www/maestro-studio"
fi

mkdir -p "$APP_DIR"
cd "$APP_DIR"

echo "=== [1/4] Estrazione del codice e dei file di build (Scale Gym + English) ==="
cat << 'ARCHIVE_EOF' | base64 -d | tar -xzf -

ARCHIVE_EOF
echo "OK: File estratti con successo in $APP_DIR."

echo ""
echo "=== [2/4] Configurazione e Commit Git Locale ==="
if [ ! -d ".git" ]; then
    git init
    git branch -M main 2>/dev/null || true
fi

git config user.name "msarti81-design"
git config user.email "msarti81@gmail.com"

git add -A .
git commit -m "Update v1.0.200: Full English translation, Scale Gym card, 5-tab tutorial ($(date '+%Y-%m-%d %H:%M:%S'))" || true

TARGET_REPO="https://github.com/msarti81-design/maestro-studio.git"
git remote add origin "$TARGET_REPO" 2>/dev/null || git remote set-url origin "$TARGET_REPO"

echo ""
echo "=== [3/4] Invio del codice a GitHub ($TARGET_REPO) ==="
echo "Push in corso verso GitHub per avviare la compilazione APK..."
if git push -u origin main --force 2>&1; then
    echo ""
    echo "✅ SUCCESS: Codice inviato a GitHub con successo!"
    echo "🚀 La GitHub Action per compilare l'APK Android e' partita ORA su GitHub!"
else
    echo ""
    echo "⚠️ Se richiesto token GitHub, esegui: git remote set-url origin https://<TUO_TOKEN>@github.com/msarti81-design/maestro-studio.git && git push -u origin main --force"
fi

echo ""
echo "=== [4/4] Riavvio WebApp su porta 5000 / PM2 ==="
pm2 delete maestro 2>/dev/null || true
pm2 restart maestro-studio --update-env 2>/dev/null || PORT=5000 pm2 start server.js --name "maestro-studio" --cwd "$APP_DIR"
pm2 save 2>/dev/null || true

echo ""
echo "=========================================================="
echo " AGGIORNAMENTO COMPLETATO!"
echo " 🌐 Sito Web VPS: http://freeserv.it/Song#piano"
echo " 📦 Repository GitHub: https://github.com/msarti81-design/maestro-studio"
echo " 📱 Stato APK: Controlla la tab 'Actions' su GitHub"
echo "=========================================================="
